<!doctype html><html><head><meta charset="utf-8"><title>{{ $invoice->invoice_number }}</title><style>body{font-family:DejaVu Sans,sans-serif;font-size:12px;color:#222}h1{color:#0d6efd}.header{display:flex;justify-content:space-between;margin-bottom:30px}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:left}th:last-child,td:last-child{text-align:right}.totals{margin-left:auto;width:260px;text-align:right;margin-top:20px}.total{font-size:18px;font-weight:bold;border-top:2px solid #333;padding-top:8px}</style></head><body><div class="header"><div><h1>INVOICE</h1><strong>{{ $invoice->invoice_number }}</strong></div><div><strong>InvoiceDesk</strong><br>Issued: {{ $invoice->issue_date->format('M d, Y') }}<br>Due: {{ optional($invoice->due_date)->format('M d, Y') ?: '—' }}</div></div><h3>Bill to</h3><p><strong>{{ $invoice->client->name }}</strong><br>{{ $invoice->client->company }}<br>{{ $invoice->client->email }}<br>{{ nl2br(e($invoice->client->address)) }}</p><table><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Total</th></tr>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>${{ number_format($item->unit_price,2) }}</td><td>${{ number_format($item->line_total,2) }}</td></tr>@endforeach</table><div class="totals">Subtotal: ${{ number_format($invoice->subtotal,2) }}<br>Discount: ${{ number_format($invoice->discount,2) }}<br>Tax: ${{ number_format($invoice->tax_amount,2) }}<div class="total">Total: ${{ number_format($invoice->total,2) }}</div>Paid: ${{ number_format($invoice->amount_paid,2) }}<br>Balance: ${{ number_format($invoice->balance_due,2) }}</div>@if($invoice->notes)<p><strong>Notes:</strong> {{ $invoice->notes }}</p>@endif</body></html>
